            sb.AppendLine($"return await client.PostAsync<{inputType}, {returnType}>(");
            sb.Indent();
            sb.AppendLine($"\"{currentNsid}\",");
            sb.AppendLine($"{proxyServiceDid},");
            sb.AppendLine(hasInput ? "input," : "null,");
