        sb.Unindent();

        sb.OpenBrace();
        sb.AppendLine($"return client.SubscribeAsync<{currentNamespace}.{interfaceName}>(");
        sb.Indent();
        sb.AppendLine($"\"{currentNsid}\",");
        sb.AppendLine(hasParameters ? "parameters?.ToQueryParameters()," : "null,");
        sb.AppendLine("cancellationToken);");
        sb.Unindent();
        sb.CloseBrace();
    }
}
